pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.max(0.0).min(capacity);

    // Strongly prefer leaving a residual that can accommodate the next item.
    if next > 0.0 {
        let compatibility = (post - next).abs();
        score += compatibility * 4.0;

        if post >= next {
            score -= 18.0;
        } else {
            score += 10.0 + (next - post) * 0.35;
        }
    }

    // Relative placement quality: favor below-average residual space.
    score += (post - mean) * 1.75;

    // Avoid wasting space when the current bin remains serviceable.
    if post > 0.0 && post < item.min(10.0) {
        score += 20.0;
    }

    // Dead space is especially costly when this is the final fitting bin.
    if fitting_bins_count == 1 {
        score += (post / capacity) * 12.0;
        if post >= next && next > 0.0 {
            score -= 14.0;
        }
    }

    // A new bin has no legacy residual; reward it only when it preserves a
    // useful future fit and avoids committing the current item to poor space.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next > 0.0 && bin_capacity - item >= next {
            score -= 11.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    // Late in a long stream, favor consolidation and exact next-item matching.
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    if next > 0.0 {
        let exact_match = 1.0 - ((post - next).abs() / capacity);
        score -= exact_match * (8.0 + 10.0 * progress);
    }

    // Penalize opening many bins, but only mildly for an empty-bin candidate.
    if open_bins_count > 1 {
        score += (open_bins_count as f64 - 1.0) * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
