    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let mut score = post;

    let harmonic_class = ((item_size * 7 + 3) % 11) as f64;
    score += harmonic_class * 0.35;

    let post_fraction = post / capacity;
    let next_fraction = next / capacity;
    let item_fraction = item / capacity;

    score += ((post_fraction * 10.0).round() - (next_fraction * 10.0).round()).abs() * 1.7;
    score += (post_fraction - next_fraction) * 8.0;

    if post == 0 {
        score -= 18.0;
    } else if post < item.min(next.max(1)) {
        score += 12.0;
    }

    if next > 0.0 && post >= next {
        score -= 9.0;
    } else if next > 0.0 && post + next <= capacity {
        score += 5.0;
    }

    if post % 10 == 0 {
        score -= 1.2;
    }
    if item_size % 10 == 0 {
        score -= 0.8;
    }

    let residual_gap = (mean_residual - residual).abs();
    score += residual_gap * 0.035;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.5;
    }

    if open_bins_count > 0 {
        let pressure = (open_bins_count as f64) / (total_items.max(1) as f64).sqrt();
        score += pressure * 0.4;
    }

    if bin_residual == bin_capacity {
        score += 7.0;
        if next == 0.0 {
            score += 2.0;
        }
    } else if item_fraction > 0.65 {
        score += 2.5;
    }

    score += (1.0 - progress) * 1.1;
    score += (post / capacity) * 1.4;
    score -= (item / capacity) * 0.45;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let size = item_size as f64;
    let cap = bin_capacity as f64;
    let is_new = bin_residual >= bin_capacity;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };

    // Penalize residual space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0 + (20 - post_residual) as f64 * 0.6;
    }

    // Tight placements are strongly preferred; loose fits are mildly discouraged.
    let utilization = size / cap;
    score += (1.0 - utilization) * 18.0;

    // Prefer bins whose residual remains compatible with the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            if post_residual >= next_item_size + 10 {
                score -= 6.0;
            }
        } else {
            score += 14.0;
        }
    }

    // A singleton fitting bin should be used rather than opening another bin.
    if fitting_bins_count == 1 {
        score -= 28.0;
    }

    // Pressure from many open bins favors consolidating into existing bins.
    if open_bins_count > 1 {
        score -= (open_bins_count as f64).min(8.0) * 3.0;
    }

    // Penalize excessive residual relative to the average open-bin residual.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.16;

    // Empty bins are reserved for genuinely necessary openings.
    if is_new {
        score += 24.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if progress > 0.5 {
            score += 4.0;
        }
    }

    score
}

